// Builds the Ossian Reach Handbook journal pack (src/packs/reach-handbook/) from the extracted
// setting text in docs/setting/reach-handbook/ (B45). Book One world material — lore, sites,
// Director frames and maps. Not RAW, and not a second bestiary.
//
// Inputs (all generated by the B45 extraction, the PDF itself never enters the repo):
//   docs/setting/reach-handbook/chapters.json  — [{ file, title, folder }] in reading order
//   docs/setting/reach-handbook/NN-*.md        — one chapter per file, H1 title, "##" sections
//   docs/setting/reach-handbook/ART-INDEX.md   — table of shipped art under assets/reach-handbook/
//
// One JournalEntry per chapter, split into pages at "##", inside compendium folders. The Maps
// journal is built from the art index so every shipped map has an image page.
//
// Run:  node tools/reach-handbook-to-journals.mjs   then   node tools/build-packs.mjs  (Foundry closed)
// Do NOT regen this pack wholesale unless you re-inject B72 district battle-map
// pages (they are not in the markdown sources and a full regen drops them).
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, readdirSync, mkdirSync, rmSync, existsSync } from "node:fs";
import { join } from "node:path";
import { foundryRequire } from "./lib/foundry-require.mjs";

const showdown = foundryRequire("showdown");
const SHOWDOWN_OPTIONS = { disableForced4SpacesIndentedSublists: true, noHeaderId: true, parseImgDimensions: true, strikethrough: true, tables: true, tablesHeaderId: true };
const converter = new showdown.Converter(SHOWDOWN_OPTIONS);

const MODULE_ID = "draw-steel-ghostwire";
const SRC = "docs/setting/reach-handbook";
const ART = "assets/reach-handbook";
const OUT = "src/packs/reach-handbook";
const B62 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
const stableId = seed => [...createHash("sha256").update("gw-reach-handbook:" + seed).digest()].slice(0, 16).map(b => B62[b % 62]).join("");
const read = p => readFileSync(p, "utf8").replace(/\r\n/g, "\n");

// Compendium folders, in sidebar order. Keys match chapters.json "folder" values.
// build-packs.mjs pairs a compendium folder with a source subdirectory: each folder's journals live
// in its own directory beside that directory's _folder.json.
const FOLDERS = [
  { key: "Front", id: "gwHandbookFront0", dir: "front", label: "Front" },
  { key: "Strata", id: "gwHandbookStrata", dir: "strata", label: "The Reach — Vertical Hive" },
  { key: "Flats", id: "gwHandbookFlats0", dir: "flats", label: "The Flats — Streets & Districts" },
  { key: "Grid", id: "gwHandbookGrid00", dir: "grid", label: "The Grid & the Boundary" },
  { key: "Cinderhold", id: "gwHandbookCinder", dir: "cinderhold", label: "Cinderhold & the Wastes Gate" },
  { key: "Threats", id: "gwHandbookThreat", dir: "threats", label: "Threats & Critters (lore)" },
  { key: "Maps", id: "gwHandbookMaps00", dir: "maps", label: "Maps & Plates" },
];

const manifestPath = join(SRC, "chapters.json");
if (!existsSync(manifestPath)) throw new Error(`${manifestPath} missing — run the B45 text extraction first`);
const manifest = JSON.parse(read(manifestPath));
const known = new Set(FOLDERS.map(f => f.key));
for (const c of manifest) if (!known.has(c.folder)) throw new Error(`chapters.json: unknown folder "${c.folder}" for ${c.file}`);

/** Split a chapter's markdown into pages at "##" (the intro before the first "##" becomes Overview). */
function splitPages(md) {
  const body = md.replace(/^#\s+.+\n+/, "");
  const pages = [];
  let current = { name: "Overview", lines: [] };
  let fence = false;
  for (const line of body.split("\n")) {
    if (/^```/.test(line)) fence = !fence;
    const h2 = !fence && /^##\s+(.+?)\s*$/.exec(line);
    if (h2) { pages.push(current); current = { name: h2[1].trim().replace(/\*\*/g, ""), lines: [] }; }
    else current.lines.push(line);
  }
  pages.push(current);
  return pages
    .map(p => ({ name: p.name, markdown: p.lines.join("\n").replace(/\n{3,}/g, "\n\n").trim() }))
    .filter(p => p.markdown || p.name !== "Overview");
}

/**
 * Parse ART-INDEX.md. The table is column-titled ("Output path", "Depicts", "Belongs with",
 * "Src page"), so read the header row and index by name — positional guessing would name every
 * map page "map (district)".
 */
function readArtIndex() {
  const path = join(SRC, "ART-INDEX.md");
  if (!existsSync(path)) return [];
  const cellsOf = line => line.split("|").map(c => c.trim()).filter((c, i, a) => i > 0 && i < a.length - 1);
  const rows = [];
  let col = null;
  for (const line of read(path).split("\n")) {
    if (!line.trim().startsWith("|")) continue;
    const cells = cellsOf(line);
    if (!col && cells.some(c => /output path/i.test(c))) {
      col = {};
      cells.forEach((c, i) => {
        if (/output path/i.test(c)) col.file = i;
        else if (/^depicts/i.test(c)) col.depicts = i;
        else if (/belongs with/i.test(c)) col.belongs = i;
        else if (/src page/i.test(c)) col.page = i;
      });
      continue;
    }
    if (!col) continue;
    const file = (/(assets[\\/]reach-handbook[\\/][\w.\-]+)/.exec(cells[col.file] ?? "") ?? [])[1]?.replace(/\\/g, "/");
    if (!file || !existsSync(file)) continue;
    const depicts = cells[col.depicts] ?? "";
    // Page name: the first clause of "Depicts" ("Switchboard district map, 10 numbered …").
    const name = (depicts.split(/\s+[—–]\s+|,\s/)[0] || file.split("/").pop()).slice(0, 60);
    rows.push({
      file, name,
      caption: depicts || file.split("/").pop(),
      belongs: cells[col.belongs] ?? "",
      page: cells[col.page] ?? "",
    });
  }
  return rows;
}

function page(entryId, index, name, markdown) {
  const _id = stableId(`page:${entryId}:${index}:${name}`);
  return {
    _id, _key: `!journal.pages!${entryId}.${_id}`,
    name, type: "text", sort: (index + 1) * 100000,
    title: { show: true, level: 1 }, image: {}, video: { controls: true, volume: 0.5 }, src: null, system: {},
    text: { format: 2, markdown, content: converter.makeHtml(markdown) },
    category: null, ownership: { default: -1 }, flags: {},
  };
}

mkdirSync(OUT, { recursive: true });
for (const entry of readdirSync(OUT)) rmSync(join(OUT, entry), { recursive: true, force: true });

const lang = JSON.parse(readFileSync("lang/en.json", "utf8"));
const journalsLang = {}, foldersLang = {};
const used = new Set();
let journalCount = 0, pageCount = 0;

// Front matter gets a short "how this pack fits" page ahead of the book's own front chapter.
const FRONT_NOTE = [
  "This compendium is the **Ossian Reach Handbook**: Book One world material — the hive, its strata, the",
  "streets of the Flats, the Grid above, Cinderhold at the wastes gate, and the things that live in the gaps.",
  "It is **lore, not rules**.",
  "",
  "- **Rules** live in the **Ghostwire Rulebook** compendium (`docs/raw/` is their source of record).",
  "- **The Wired** side of the Flats — matrix nodes, ICE postures, district master nodes — lives in the",
  "  **Ghostwire — The Wired: Flats** compendium. This pack owns the **physical** street lore; that one owns the network.",
  "- **Stat blocks** live in the **Ghostwire Bestiary**. The Threats chapters here are ecology and rumour;",
  "  where a creature has an Actor, it is named so you can find it.",
  "- **Random events** for these zones are in the **Ghostwire Reach Events** tables.",
  "",
  "*Old edition mechanics — tier ladders, superseded chrome grades, pasted combat math — were scrubbed on import;",
  "`docs/setting/reach-handbook/EXTRACT-NOTES.md` records exactly what changed.*",
].join("\n");

for (const [i, chapter] of manifest.entries()) {
  const path = join(SRC, chapter.file);
  if (!existsSync(path)) throw new Error(`chapters.json lists ${chapter.file}, which does not exist`);
  const folder = FOLDERS.find(f => f.key === chapter.folder);
  used.add(folder.key);

  const pages = splitPages(read(path));
  if (folder.key === "Front" && i === 0) pages.unshift({ name: "About This Compendium", markdown: FRONT_NOTE });

  const entryId = stableId(chapter.file);
  const key = chapter.file.replace(/\.md$/, "").replace(/[^a-z0-9]+/gi, " ").trim().split(" ").map(w => w[0].toUpperCase() + w.slice(1)).join("");
  journalsLang[key] = chapter.title;

  mkdirSync(join(OUT, folder.dir), { recursive: true });
  writeFileSync(join(OUT, folder.dir, chapter.file.replace(/\.md$/, ".json")), JSON.stringify({
    _id: entryId, _key: `!journal!${entryId}`,
    name: `GHOSTWIRE.ReachHandbook.Journals.${key}`,
    folder: folder.id, sort: (i + 1) * 100000, categories: [],
    pages: pages.map((p, n) => page(entryId, n, p.name, p.markdown)),
    ownership: { default: 0 },
    flags: { [MODULE_ID]: { source: `${SRC}/${chapter.file}` } },
  }, null, 2) + "\n");
  journalCount++; pageCount += pages.length;
}

// Maps journal: one image-bearing page per shipped asset, plus an index page.
const art = readArtIndex();
if (art.length) {
  const folder = FOLDERS.find(f => f.key === "Maps");
  used.add("Maps");
  const entryId = stableId("maps");
  const index = ["Every map and plate carried over from the Handbook. Each page below is one image; the district maps",
    "have their numbered key baked into the artwork, and those numbers match the location headings in that",
    "district's gazetteer chapter. Full provenance is in `docs/setting/reach-handbook/ART-INDEX.md`.", "",
    "| Plate | Book page | Goes with |", "|---|---|---|",
    ...art.map(a => `| ${a.name} | ${a.page} | ${a.belongs} |`)].join("\n");
  const pages = [
    { name: "Plate Index", markdown: index },
    ...art.map(a => ({
      name: a.name,
      markdown: `![${a.name}](modules/${MODULE_ID}/${a.file})\n\n*${a.caption}*${a.belongs ? `\n\n**Goes with:** ${a.belongs}` : ""}`,
    })),
  ];
  journalsLang.Maps = "Maps & Plates";
  mkdirSync(join(OUT, folder.dir), { recursive: true });
  writeFileSync(join(OUT, folder.dir, "maps.json"), JSON.stringify({
    _id: entryId, _key: `!journal!${entryId}`,
    name: "GHOSTWIRE.ReachHandbook.Journals.Maps",
    folder: folder.id, sort: (manifest.length + 1) * 100000, categories: [],
    pages: pages.map((p, n) => page(entryId, n, p.name, p.markdown)),
    ownership: { default: 0 },
    flags: { [MODULE_ID]: { source: `${SRC}/ART-INDEX.md` } },
  }, null, 2) + "\n");
  journalCount++; pageCount += pages.length;
}

// Only ship folders that actually hold something.
for (const [n, folder] of FOLDERS.filter(f => used.has(f.key)).entries()) {
  foldersLang[folder.key] = folder.label;
  mkdirSync(join(OUT, folder.dir), { recursive: true });
  writeFileSync(join(OUT, folder.dir, "_folder.json"), JSON.stringify({
    _id: folder.id, _key: `!folders!${folder.id}`,
    name: `GHOSTWIRE.ReachHandbook.Folders.${folder.key}`,
    type: "JournalEntry", folder: null, sort: (n + 1) * 100000,
    flags: {}, color: null, description: "", sorting: "m",
  }, null, 2) + "\n");
}

lang.GHOSTWIRE.COMPENDIUM.reachHandbook = "Ghostwire — Ossian Reach Handbook";
lang.GHOSTWIRE.ReachHandbook = { Folders: foldersLang, Journals: journalsLang };
writeFileSync("lang/en.json", JSON.stringify(lang, null, 2) + "\n");
console.log(`reach-handbook: ${journalCount} journals, ${pageCount} pages, ${used.size} folders, ${art.length} art pages`);
